import 'package:flutter/material.dart';
import '../../models/jobseeker/jobseeker_models.dart';
import '../../services/api_client.dart';
import '../../services/jobseeker/jobseeker_service.dart';
import '../../theme/app_theme.dart';

class JobSeekerProfileScreen extends StatefulWidget{const JobSeekerProfileScreen({super.key,required this.service});final JobSeekerService service;@override State<JobSeekerProfileScreen> createState()=>_State();}
class _State extends State<JobSeekerProfileScreen>{JobSeekerProfile? profile;List<JobSeekerSkill> skills=[];List<SkillCatalogItem> catalog=[];JobSeekerCv? cv;bool loading=true;String? error;
@override void initState(){super.initState();_load();}
Future<void> _load()async{setState(()=>loading=true);try{final p=await widget.service.getProfile();final s=await widget.service.getSkills();final c=await widget.service.getSkillCatalog();final v=await widget.service.getCv();if(mounted)setState((){profile=p;skills=s;catalog=c;cv=v;error=null;});}on ApiException catch(e){if(mounted)setState(()=>error=e.message);}finally{if(mounted)setState(()=>loading=false);}}
Future<void> _editProfile()async{final p=profile!;final name=TextEditingController(text:p.fullName),headline=TextEditingController(text:p.headline),loc=TextEditingController(text:p.location),bio=TextEditingController(text:p.bio),linkedin=TextEditingController(text:p.linkedInUrl),github=TextEditingController(text:p.gitHubUrl),portfolio=TextEditingController(text:p.portfolioUrl);final save=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:const Text('Edit profile'),content:SizedBox(width:500,child:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:name,decoration:const InputDecoration(labelText:'Full name')),TextField(controller:headline,decoration:const InputDecoration(labelText:'Headline')),TextField(controller:loc,decoration:const InputDecoration(labelText:'Location')),TextField(controller:bio,maxLines:3,decoration:const InputDecoration(labelText:'Bio')),TextField(controller:linkedin,decoration:const InputDecoration(labelText:'LinkedIn URL')),TextField(controller:github,decoration:const InputDecoration(labelText:'GitHub URL')),TextField(controller:portfolio,decoration:const InputDecoration(labelText:'Portfolio URL'))]))),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Save'))]));if(save!=true)return;try{final updated=await widget.service.updateProfile(JobSeekerProfile(fullName:name.text.trim(),email:p.email,headline:headline.text.trim(),location:loc.text.trim(),bio:bio.text.trim(),linkedInUrl:linkedin.text.trim(),gitHubUrl:github.text.trim(),portfolioUrl:portfolio.text.trim()));if(mounted)setState(()=>profile=updated);}on ApiException catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.message)));}}
Future<void> _addSkill()async{final existing=skills.map((e)=>e.skillId).toSet();final options=catalog.where((e)=>!existing.contains(e.id)).toList();if(options.isEmpty){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('No more skills available to add.')));return;}String selected=options.first.id;double level=3;final ok=await showDialog<bool>(context:context,builder:(c)=>StatefulBuilder(builder:(c,setLocal)=>AlertDialog(title:const Text('Add skill'),content:Column(mainAxisSize:MainAxisSize.min,children:[DropdownButtonFormField<String>(initialValue:selected,items:options.map((s)=>DropdownMenuItem(value:s.id,child:Text(s.name))).toList(),onChanged:(v){if(v!=null)setLocal(()=>selected=v);},decoration:const InputDecoration(labelText:'Skill')),const SizedBox(height:12),Text('Proficiency: ${level.round()}/5'),Slider(value:level,min:1,max:5,divisions:4,onChanged:(v)=>setLocal(()=>level=v))]),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Add'))])));if(ok==true){try{await widget.service.addSkill(selected,level.round());await _load();}on ApiException catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.message)));}}}
Future<void> _skillMenu(JobSeekerSkill s)async{final action=await showModalBottomSheet<String>(context:context,builder:(c)=>SafeArea(child:Wrap(children:[ListTile(title:Text(s.name,style:const TextStyle(fontWeight:FontWeight.w800))),ListTile(leading:const Icon(Icons.tune_rounded),title:const Text('Change proficiency'),onTap:()=>Navigator.pop(c,'edit')),ListTile(leading:const Icon(Icons.delete_outline_rounded),title:const Text('Remove skill'),onTap:()=>Navigator.pop(c,'delete'))])));if(!mounted)return;if(action=='delete'){await widget.service.deleteSkill(s.skillId);await _load();}else if(action=='edit'){double level=s.proficiencyLevel.toDouble();final ok=await showDialog<bool>(context:context,builder:(c)=>StatefulBuilder(builder:(c,setLocal)=>AlertDialog(title:Text(s.name),content:Column(mainAxisSize:MainAxisSize.min,children:[Text('Proficiency: ${level.round()}/5'),Slider(value:level,min:1,max:5,divisions:4,onChanged:(v)=>setLocal(()=>level=v))]),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Save'))])));if(ok==true){await widget.service.updateSkill(s.skillId,level.round());await _load();}}}
@override Widget build(BuildContext c){if(loading)return const Center(child:CircularProgressIndicator());if(error!=null)return Center(child:Text(error!));final p=profile!;return RefreshIndicator(onRefresh:_load,child:ListView(padding:const EdgeInsets.all(16),children:[Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[CircleAvatar(radius:26,child:Text(p.fullName.isEmpty?'J':p.fullName[0].toUpperCase())),const SizedBox(width:12),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(p.fullName,style:const TextStyle(fontWeight:FontWeight.w900,fontSize:18)),Text(p.email,style:const TextStyle(color:AppTheme.muted)),if(p.headline.isNotEmpty)Text(p.headline)])),IconButton(onPressed:_editProfile,icon:const Icon(Icons.edit_outlined))]),if(p.location.isNotEmpty)...[const SizedBox(height:10),Text('📍 ${p.location}')],if(p.bio.isNotEmpty)...[const SizedBox(height:12),Text(p.bio,style:const TextStyle(height:1.4))]]))),const SizedBox(height:12),Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[const Expanded(child:Text('Skills',style:TextStyle(fontWeight:FontWeight.w900,fontSize:17))),IconButton(onPressed:_addSkill,icon:const Icon(Icons.add_circle_outline_rounded))]),if(skills.isEmpty)const Text('No skills added yet.',style:TextStyle(color:AppTheme.muted)) else ...skills.map((s)=>ListTile(contentPadding:EdgeInsets.zero,title:Text(s.name),subtitle:Text('Proficiency ${s.proficiencyLevel}/5'),trailing:IconButton(onPressed:()=>_skillMenu(s),icon:const Icon(Icons.more_vert_rounded))))]))),const SizedBox(height:12),Card(child:ListTile(contentPadding:const EdgeInsets.all(16),leading:const Icon(Icons.description_outlined,color:AppTheme.violet),title:const Text('CV',style:TextStyle(fontWeight:FontWeight.w800)),subtitle:Text(cv==null?'No CV uploaded yet.':'${cv!.fileName} • ${(cv!.fileSizeBytes/1024).toStringAsFixed(0)} KB'),trailing:Icon(cv==null?Icons.warning_amber_rounded:Icons.check_circle_rounded,color:cv==null?Colors.orange:Colors.green)))]));}}
